import Config

# Listener, secret and origin checks live in config/runtime.exs (plain HTTP behind the authenticated proxy).

# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix assets.deploy` task,
# which you should run after static files are built and
# before starting your production server.
config :testme, RiichiAdvancedWeb.Endpoint, cache_static_manifest: "priv/static/cache_manifest.json"

# Do not print debug messages in production
# config :logger, level: :info

# Runtime production configuration, including reading
# of environment variables, is done on config/runtime.exs.

# Disable swoosh api client
config :swoosh, :api_client, false

# Enable dev routes for dashboard and mailbox
config :riichi_advanced, dev_routes: false

# serve files in the toplevel priv (instead of the one in the _build directory)
config :riichi_advanced, :priv_dir, Path.join(File.cwd!(), "priv")
